const item = $input.first();
const binaries = item.binary || {};
const keys = Object.keys(binaries);
if (keys.length !== 1) throw new Error(keys.length ? `Ожидается один архив ZIP или 7Z. Получено файлов: ${keys.length}` : 'Прикрепите один архив ZIP или 7Z.');
const sourceKey = keys[0];
const archive = binaries[sourceKey];
const fileName = String(archive.fileName || sourceKey);
const extension = (fileName.match(/\.([^.]+)$/)?.[1] || '').toLowerCase();
if (!['zip', '7z'].includes(extension)) throw new Error(`Неподдерживаемый формат: ${fileName}. Разрешены ZIP и 7Z.`);
const tenderName = String(item.json?.tenderName || item.json?.chatInput || fileName || 'documents').trim();
return [{ json: { tenderName, originalFileName: fileName }, binary: { archive } }];

const result = $input.first().json;
const jobId = String(result.jobId || '');
if (!jobId) throw new Error('Worker не вернул идентификатор задачи.');
return [{ json: { status: result.status || 'queued', jobId, output: `Задача принята: ${jobId}. Подбор выполняется в фоне; готовый Excel появится в папке Яндекс Диска «Тендеры автоподбор».` } }];
